export const meta = {
  name: "implement-review",
  description:
    "Have a holyagent writer do its Assignment, then an independent reviewer judge that work, for each pair",
  phases: [
    { title: "Implement", detail: "the writer of each pair" },
    { title: "Review", detail: "the reviewer of each pair, once its writer is done" },
  ],
}
// Generated by packages/integrations/claude/build.ts from packages/integrations/claude/src/workflows/implement-review.js and packages/integrations/claude/src/workflows/shared.js; edit the source and rebuild.
// The report every specialist returns, and the call that runs one dispatched Assignment.
const REPORT = {
  type: "object",
  properties: {
    status: { type: "string", enum: ["done", "partial", "blocked"] },
    changed_paths: { type: "array", items: { type: "string" } },
    checks: {
      type: "array",
      items: {
        type: "object",
        properties: { command: { type: "string" }, exit: { type: "integer" } },
        required: ["command", "exit"],
      },
    },
    blockers: { type: "array", items: { type: "string" } },
    notes: { type: "array", items: { type: "string" } },
    evidence: {
      type: "array",
      items: {
        type: "object",
        properties: { key: { type: "string" }, support: { type: "string" } },
        required: ["key", "support"],
      },
    },
  },
  required: ["status", "changed_paths", "checks", "blockers", "notes", "evidence"],
}

const REPORT_REQUEST =
  "\n\nReturn your report as the structured output, not as text. Give each evidence line as an evidence entry: key is the criterion text or evidence label exactly as written, support is what shows it. List every check you ran in checks, and anything left undone in blockers."

// An entry is {id, agent, model, effort, prompt} as `assignment dispatch` prints it.
const runEntry = (entry, phase, addition = "") =>
  agent(entry.prompt + addition + REPORT_REQUEST, {
    agentType: entry.agent.includes(":") ? entry.agent : "holyagent:" + entry.agent,
    model: entry.model,
    effort: entry.effort,
    schema: REPORT,
    label: entry.id,
    phase,
  })

const handoff = (writer) =>
  "\n\nThe writer has finished. Changed paths:\n" +
  writer.changed_paths.map((path) => "- " + path).join("\n") +
  "\nChecks it ran:\n" +
  writer.checks.map((check) => "- " + check.command + " -> exit " + check.exit).join("\n")

// Each pair is its own chain, so one pair failing does not hold back or redo the others.
const results = await pipeline(
  args.pairs,
  (pair) => runEntry(pair.writer, "Implement"),
  async (writer, pair) =>
    writer === null || writer.status === "blocked"
      ? { writer, reviewer: null }
      : { writer, reviewer: await runEntry(pair.reviewer, "Review", handoff(writer)) },
)
return args.pairs.map((pair, index) => ({
  writer: { id: pair.writer.id, report: results[index]?.writer ?? null },
  reviewer: { id: pair.reviewer.id, report: results[index]?.reviewer ?? null },
}))
